add_action( 'manage_product_posts_custom_column', 'perfectpixel_external_clicks_column_value', 10, 2 );

function perfectpixel_external_clicks_script() {
	if ( ! function_exists( 'is_woocommerce' ) || ! is_woocommerce() ) {
		return;
	}
	$single = 0;
	if ( is_product() ) {
		$product = wc_get_product( get_queried_object_id() );
		$single  = ( $product && $product->is_type( 'external' ) ) ? $product->get_id() : 0;
	}
	$data = array(
		'url'    => admin_url( 'admin-ajax.php' ),
		'single' => $single,
	);
	?>
	<script>
	( function () {
		var cfg = <?php echo wp_json_encode( $data ); ?>;
		var send = function ( id ) {
			var body = new FormData();
			body.append( 'action', 'perfectpixel_external_click' );
			body.append( 'product_id', id );
			navigator.sendBeacon ? navigator.sendBeacon( cfg.url, body ) : fetch( cfg.url, { method: 'POST', body: body, keepalive: true } );
		};
		document.addEventListener( 'click', function ( e ) {
			var loop = e.target.closest( 'a.product_type_external[data-product_id]' );
			if ( loop ) {
				send( loop.getAttribute( 'data-product_id' ) );
			} else if ( cfg.single && e.target.closest( 'form.cart .single_add_to_cart_button' ) ) {
				send( cfg.single );
			}
		} );
	} )();
	</script>
	<?php
}

function perfectpixel_external_clicks_record() {
	$product = wc_get_product( isset( $_POST['product_id'] ) ? absint( $_POST['product_id'] ) : 0 );
	if ( $product && $product->is_type( 'external' ) ) {
		$id = $product->get_id();
		update_post_meta( $id, '_perfectpixel_external_clicks', (int) get_post_meta( $id, '_perfectpixel_external_clicks', true ) + 1 );
	}
	wp_die();
}

function perfectpixel_external_clicks_column( $columns ) {
	$columns['perfectpixel_external_clicks'] = 'Κλικ εξωτερικού';
	return $columns;
}

function perfectpixel_external_clicks_column_value( $column, $post_id ) {
	if ( 'perfectpixel_external_clicks' === $column ) {
		$product = wc_get_product( $post_id );
		echo ( $product && $product->is_type( 'external' ) ) ? (int) get_post_meta( $post_id, '_perfectpixel_external_clicks', true ) : '&ndash;';
	}
}
